import{_ as r,a,b as o}from"./chunks/8891924c713e3dff2fb4.CXCRPTbV.js";import{_ as l,C as s,o as i,c as n,j as e,a as h,E as c,a5 as m}from"./chunks/framework.DNkHA0lr.js";const w=JSON.parse('{"title":"不确定性危机（为什么每个人都感到如此迷茫）","description":"","frontmatter":{"title":"不确定性危机（为什么每个人都感到如此迷茫）","originalTitle":"The Uncertainty Crisis (Why Everyone Feels So Lost)","date":"2024-08-03","originalUrl":"https://thedankoe.com/letters/the-uncertainty-crisis-why-everyone-feels-so-lost/","minutes":28,"sourceHash":"9c3ab03ac5a54d3191ae3333182fa8a2f04419893160848c9d29a548cf9f7fb1","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-uncertainty-crisis-why-everyone-feels-so-lost/"}]]},"headers":[],"relativePath":"letters/the-uncertainty-crisis-why-everyone-feels-so-lost.md","filePath":"letters/the-uncertainty-crisis-why-everyone-feels-so-lost.md"}'),d={name:"letters/the-uncertainty-crisis-why-everyone-feels-so-lost.md"};function f(u,p,g,b,k,_){const t=s("ArticleMeta");return i(),n("div",null,[p[0]||(p[0]=e("h1",{id:"不确定性危机-为什么每个人都感到如此迷茫",tabindex:"-1"},[h("不确定性危机（为什么每个人都感到如此迷茫） "),e("a",{class:"header-anchor",href:"#不确定性危机-为什么每个人都感到如此迷茫","aria-label":'Permalink to "不确定性危机（为什么每个人都感到如此迷茫）"'},"​")],-1)),c(t),p[1]||(p[1]=m('<p><a href="https://www.youtube.com/embed/5ZDqSTd-vwg?si=F68zJOQVko24qgUW" target="_blank" rel="noreferrer">观看原文视频</a></p><p><img src="'+r+'" alt=""></p><p>每次我妈给我打电话，她都会问：</p><p><em>“这个周末有什么好玩的吗？”</em></p><p>在过去的几年里，我的回答几乎总是：</p><p><em>“没，还是老样子。”</em></p><p>当然，我偶尔也会去旅行或参加些活动，这些都是她想听的，但大多数时候，我的答案只包括工作、写作、散步、举铁和吃饭。这些就是我每天做的事。</p><p>她的回应总是：</p><p><em>“噢，你应该多出去走走！你还年轻啊，丹尼尔（Daniel）！”</em></p><p>我总觉得我自己出了什么问题。</p><p>我想，她是对的。</p><p>我<em>确实应该</em>多出去走走。</p><p>我是不是在挥霍人生中最关键的几年？</p><p>我以后回想起来，会不会后悔日复一日地做着同样的老一套？</p><p>于是，我逼着自己多出门。</p><p>但我发现，我反而开始对生活感到更加迷茫和不满。</p><p>随着老妈继续打电话问那个问题，我渐渐恍然大悟。</p><p><em>“所以，这周末有什么好玩的吗？”</em></p><p>没，还是老样子。</p><p><em>“你为什么不出去找点乐子呢？”</em></p><p>好吧……</p><p>没有什么是比我每天做的事情更好玩的了。</p><p>那个问题预设了“随便做点什么”都比“老一套”更令人愉悦，但这“老一套”正是带来意义感、临在感和心流的东西。以你的巅峰状态去运作，比不断利用带来快感的消遣去填补灵魂空虚，要令人愉悦得多。</p><p>我为什么非要出去，顺从社会定义的所谓“好玩”，仅仅为了合群，装作我<em>真的在</em>做些好玩的事？</p><ul><li>熬夜打乱你的睡眠节奏，慢慢摧毁你的身心健康。</li><li>宿醉腐蚀你的大脑，破坏你的注意力，让你很难在那些真正令人愉悦而非单纯提供快感的事情上表现出色。</li><li>暴饮暴食那些被油脂、糖分以及其他任何让你上瘾的添加剂轰炸过的食物。</li></ul><p>当然，我并没有把这些话原封不动地对老妈说。我没那么粗鲁。</p><p>我也不认为这些东西应该从你的生活中彻底被根除。</p><p>偶尔出去浪一晚可以是一种极好的战术性重置。它可以迫使你感觉自己像坨屎，从而让你渴望拥有更好的状态。它可以让你展开平时不会有的对话，从而在你的工作中带来突破。它可以让你暴露在较低的意识状态下，以便你驾驭其中的内容并将其为你所用。</p><p>昨晚我家那位为了庆祝她的生日我们一起出去，玩得很开心。写下这段话时我脑子还有点晕乎乎的，但我拿什么都不换那样的夜晚。</p><p>这整个想法源自我和一个商界朋友的一场对话。</p><p>他评论说，人们之所以感到迷茫，是因为他们还没有创造出一种自己不想逃避的生活方式。</p><p>这句评论让我陷入了一个深思的兔子洞：现代世界是如何让人们注定失败的。</p><p>所以，这就是我们今天要讨论的内容：</p><ol><li>现代性的问题，以及为什么人们——尤其是年轻人——对自己的未来感到如此迷茫、困惑和不确定。</li><li>技术和信息时代提供的机遇，以及有多么少的人真正利用了它。</li><li>设定标准将如何改变你的生活（如果你想活得有目标，你必须为自己设定的 7 个标准）。</li><li>如何创造你理想的一天，从而让你不再讨厌星期一，不再觉得需要填补自我认知上的空洞。</li></ol><p>对于现在正在苦苦挣扎的人们：</p><p>一定有出路。</p><p>一定有办法在混乱中导航。</p><p>一定有办法对你的最终归宿拥有一种掌控感。</p><p>你生活在这样一个时代：你可以创造出一种让自己每天早晨都满心欢喜醒来的生活。</p><p>走出来的第一步，是理解到底是什么把你逼到了这步田地。</p><h2 id="不确定性危机-一个全方位的问题" tabindex="-1">不确定性危机：一个全方位的问题 <a class="header-anchor" href="#不确定性危机-一个全方位的问题" aria-label="Permalink to &quot;不确定性危机：一个全方位的问题&quot;">​</a></h2><blockquote><p>你感觉很糟，是因为你的潜意识知道你本可以做得更好。</p><p>— 丹·柯伊 (DAN KOE) (@thedankoe) <a href="https://twitter.com/thedankoe/status/1475819335277031427?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2021 年 12 月 28 日</a></p></blockquote><p>不确定性问题的根源在于，你外包了你的确定感。</p><p>情况是这样的：</p><p>你出生在一个有着特定信仰、价值观和标准的文化中。</p><p>随着你学会走路、跑步和说话，你的心智被塑造得与周围的人一致。你无法控制这一点。这是你生存的方式。</p><p>不知不觉中，你脑海里唯一的目标就是上学、找工作、结婚、去度几次好玩的假，然后某天退休。这些目标因家庭而异。有些家庭强加道德上的成功和宗教信仰，有些强加学业上的成功，还有些则鼓励创业上的成功。</p><p>如果你了解心理学和人类行为，你就能发现其中的问题。</p><p>深植于你心灵深处那些无意识设定的目标，塑造了你的行为方式、你的身份，以及你的意识能捕捉到哪些机会。</p><p>你有着和你父母一样的心智，而他们的心智又和他们的父母一样，代代相传。</p><p>除非……这个家族树里的某个人质疑了他们的信念，并寻求了一种更好的做事方式。</p><p>世界已经变了。</p><p>技术进步来得很快。</p><p>现在的世界和仅仅 10 年前相比，已经有了天壤之别。如果你还在用一套 100 年前的信念在运作，难怪你会感到如此迷茫。</p><p>你缺乏目标，是因为现代世界正淹没在信息之中。</p><p>你不知道如何去理清这一切。</p><p>你的信念与环境不匹配。</p><p>你把你的确定感外包给了社会、父母、老师、政府以及宗教意识形态。</p><p>现在，大量挑战你信仰的信息充斥着周围，你的注意力被分散，你的心智处于持续的混乱状态，直到你决定重新对自己的大脑进行编程。</p><p>曾经让你在局部环境中生存下来的东西，并不能帮你在这个快速变化的世界中生存并繁荣。你的父母可能没有把你推向巢外去让你学飞，所以你必须自己完成这纵身一跃。</p><p>更不用说，大多数打工人都害怕在未来 10 到 20 年内被取代。这是另一个本来可以轻松解决的干扰——只要你把命运掌握在自己手中，去开创一份事业。上周我在<a href="/letters/the-future-of-work-acquire-this-skill-stack">《工作的未来》</a>中讨论过这个问题。</p><p>如果你想学一项过去没有、未来也不会过时的技能（并且能让你成为一名深度通才，使你不可替代），那就去学习<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">高影响力写作</a>。</p><p>问题是，一个人如何改变大脑运作的代码？</p><p>你该如何编写这些代码，才能让你的生活取得有意义的进展？</p><p>在这个得益于你做一颗机器齿轮的社会中，你如何找到清晰的方向？</p><p>我们会谈到这些的。</p><p>因为在情况好转之前，它还会变得更糟。</p><h3 id="现代环境" tabindex="-1">现代环境 <a class="header-anchor" href="#现代环境" aria-label="Permalink to &quot;现代环境&quot;">​</a></h3><p>让我们来描绘一幅残酷的现代生活图景。</p><p>大多数人因为不必要的阿德拉（Adderall）处方、手机和各种分心事物而导致多巴胺枯竭，最终引发快感缺乏症——也就是无法感受到快乐。既然人们已经到了“正常”状态就是感觉像坨屎的地步，他们就会不择手段地试图去感受点什么，哪怕任何感觉都行。</p><p>你处于持续的生存和压力状态下。</p><p>你的视野狭隘，只能注意到那些能让你获得短暂快感的捷径机会。</p><p>处于这种低层级的意识状态中，你是机械的、动物性的。你选择去追求社会分配给你的目标。你没有把重点放在解决那些伴随你成长、让你变得独特且有价值的独特问题上。为了顺从别人对你的期望，你忽视了自己的健康、财务和思想，现在这些问题在周围制造着混乱，而你却根本不知道发生了什么。</p><p>普通人往肚子里狂塞加工食品。</p><p>他们每次看到社交媒体上的帖子都会产生情绪反应。</p><p>他们觉得只要有机会，就有必要去争论并证明自己的价值。</p><p>除此之外，他们从不出去晒太阳。</p><p>他们整天盯着屏幕。</p><p>他们坐在荧光灯照射的格子间里。</p><p>他们的工作缺乏挑战和意义。</p><p>所有这些都相互反馈，并衍生出更多的问题。</p><p>你的性欲受到了打击，因为你的雌激素和催乳素高得离谱。</p><p>你的睾酮水平直线下降。</p><p>你的身体变得松弛肥胖，你开始脱发，胸前冒出的男性乳房让你感到自卑。你开始以一种弯腰驼背、缺乏自信的姿势走路，并想要把自己藏起来，与世隔绝。</p><p>对于女性，也有类似的荷尔蒙失调现象。</p><p>避孕药像糖果一样被随意开出。</p><p>抗抑郁药成了心理健康的“常规”选择，因为它们比让人经历简单生活方式改变所带来的轻微不适更赚钱。但是，既然你以前从未进行过简单的生活方式改变，你的大脑就会说服你这件事难如登天，然后你一有机会就把这个借口投射出来，而不是干脆去做出改变。</p><p>无论男女，都缺乏精力或心思去结识新朋友、锻炼身体或改变他们的习惯。</p><p>在社会层面上，阳刚与阴柔的平衡正越来越趋向中性化。没有了两极分化。我们在对抗自然法则，并因此承受着巨大的痛苦。我并不是说解决办法是退回到没有技术的时代并“回归传统”。我的建议是，去融入并适应现代环境。解决你自己的问题。</p><p>除此之外，你的潜意识也知道，混乱正在呈指数级增长。</p><p>熵增源于你缺乏努力，由于你对生活无所作为，你开始慢慢溺水，而这只会给已经非常糟糕的境况增添更多压力。</p><p>改变的第一步就是意识到这一切。</p><p>你必须静下心来，沉思这一切，并且感到出离愤怒，以至于除了反抗别无选择。</p><p>然后，带着那种全新的精神能量源，利用触手可及的丰富信息去自我教育，追求新的目标，把自己从泥潭里挖出来。</p><p>不确定性是一个全方位的问题。</p><p>你的环境、你的荷尔蒙、你的心态、你的工作、你的生活方式、你的文化、你的社会……所有这些要么能为你所用，要么能把你死死按在地上摩擦。</p><p>解药就是变得在多维度上强悍起来。</p><p>在做任何事之前，你必须先照顾好你的思想、身体和财务状况。</p><p>你通过改变自己，并让你的决定在意识中荡起涟漪来改变世界。</p><p>但还是那句话……</p><p>在情况好转之前，它还会变得更糟。</p><h3 id="年轻人注定要失败" tabindex="-1">年轻人注定要失败 <a class="header-anchor" href="#年轻人注定要失败" aria-label="Permalink to &quot;年轻人注定要失败&quot;">​</a></h3><p>财富和繁荣就在这里。</p><p>它们只是没有被平均分配。</p><p>登录社交媒体，不难看到有人在 30 岁甚至 21 岁之前就赚了几百万美元，因为他们看到了信息经济的机遇。这对老一辈人来说是不可能的。他们无法理解。</p><p>所以，如果你不重视绝对的自力更生，你就会被抛弃在一边。</p><p>为什么？</p><p>因为制定规则的人全都来自老一辈。</p><p>社会是由那些处于顶层的人塑造的。</p><p>以传统方式获得财富和繁荣的机会——上学、找工作、买房、结婚等——都受到那些制定法律的人的影响。</p><p>房价从疫情前到现在翻了一番，所以人们宁愿把钱挥霍在出门旅行“寻找自我”上。他们放弃了投资自己的未来，因为即使是拥有一份体面高薪工作的人，也几乎不可能做到这一点。高薪工作不再高薪，因为生存成本在不断增加。</p><p>年轻人不交配也不生孩子，因为他们负担不起，而且他们就是没有这个欲望。他们的荷尔蒙和心理健康简直烂在垃圾桶里。</p><p>因此，我们唯一花时间陪伴的，是我们在社交媒体上的数字朋友、我们的另一半（如果你足够成熟的话）和我们的密友（如果你足够幸运的话）。如果你不发展生活中的社交方面，现代生活会变得极其孤独。</p><p>言归正传……</p><p>那些80岁的立法者，他们的孩子都快60岁了。</p><p>他们仍然需要打电话给侄子寻求技术支持，以学习如何在一台病毒泛滥的20年老电脑上打开电子邮件。</p><p>我不应该还需要去解释老一辈的价值观和信仰是如何影响他们做出的决定，以及这如何阻碍了社会看到进步。</p><p>立法者偏袒他们自己和他们的孩子。</p><p>这意味着，你通往财富和繁荣的唯一路径，就是走一条完全不同的路。</p><p>去忘记并反抗你所熟知的“唯一出路”。</p><p>敞开心扉，设定新标准，并让自己成长以配得上它们。</p><h2 id="信息时代的机遇" tabindex="-1">信息时代的机遇 <a class="header-anchor" href="#信息时代的机遇" aria-label="Permalink to &quot;信息时代的机遇&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><p>这并不是为了给你提供日常的虚无主义剂量，好让你说服自己保持现状。</p><p>恰恰相反。</p><p>它是为了让你生气、心烦，让你对自己感到愤怒，从而最终获得做出改变的清醒认识。就像弹弓一样，你利用这种负能量启动，然后让势能接管一切。你通过行动和努力来培养积极的哲学。</p><p>你需要的是一个机会。</p><p>而你身边有的是机会。</p><p>解决你问题的方案是技术、信息和效率。</p><p>上学找工作是一条过时的路。</p><p>自我教育、自我提升和创业是完全掌控个人思想、身体和财务的唯一途径。</p><p>看在老天的份上，你正经历着第二次文艺复兴。</p><p>难道你看不出来吗？</p><p>个人正在利用互联网消除前几代人的局限性。</p><p>你不再需要上名校去建立能带来不可思议工作的人脉。你所需要的只是在互联网上发布一篇有价值的内容，让世界另一端的人看到。或者，你可以使用那个你以为只能用来给朋友发表情包的私信（DM）功能——当然，这需要一点社交技巧和说服力。</p><p>你不再需要拿着简历去海投那些你根本不想要的平庸工作。你的个人品牌就是你的公开简历，让受众根据你提供的价值来关注你。</p><p>你不再需要在一个你不在乎的公司里扮演一个专业的角色。你不再需要做别人机器上的一个齿轮，为别人推销产品。多亏了技术，你可以用接近零成本打造一个产品或服务，吸引受众，并快速获得那些能让你运营一人企业（one-person business）的技能。</p><p>但是，有些人仍然无视这个机会。</p><p>他们没有意识到这就是现代生存之道。</p><p>是的，现在，正是互联网、社交媒体和信息让你能够创造理想的生活方式。</p><p>时代变了。如果你仍以你拒绝抛弃的10到50年前的信念来行事，你赢不了。那些控制着你的思想，把任何新事物都称为“骗局”的信念。</p><p>所有伟大的想法在它们于社会中扎根之前，都会被视为骗局。但到那时，下一个伟大的“骗局”已经在酝酿中，只有聪明人才能抓住机会（既不骗人也不被骗）。</p><p>是的，真正的骗局是非常现实存在的。我不怀疑这一点。但一点点批判性思维就能大有帮助。</p><p>如果你想加入我这个已经让无数个人得以追求其毕生事业的“骗局”，去看看<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">数字经济学（Digital Economics）</a>，学习那些学校里不会教你的技能。</p><p>换句话说，他们在未来上冒险，并在这一过程中创造了未来。</p><p>世界上的冒险者通过推动他们认为值得为之努力的新想法来创造社会。他们不会干坐着等待，直到这些想法被稀释并被大众所接受。因为到那时，它就不再是机会，而是任务。你做它只是因为别人都在做。</p><p>现在的问题是：</p><p>为什么我看不到新机会并采取行动？</p><p>因为你的标准根本不存在。</p><h3 id="设定标准将改变你的生活" tabindex="-1">设定标准将改变你的生活 <a class="header-anchor" href="#设定标准将改变你的生活" aria-label="Permalink to &quot;设定标准将改变你的生活&quot;">​</a></h3><blockquote><p>你的生活很糟糕，因为你的标准太低了，以至于你能接受自己糟糕的生活。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1714297471906549825?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2023年10月17日</a></p></blockquote><p>你的生活很糟糕，是因为你在过去一年里做出的成千上万个微小的选择。</p><p>你没有做出能导向一份有目标的职业的选择。</p><p>你没有做出能导向令人满意的人际关系的选择。</p><p>你没有做出能导向健康且充满美感的身材的选择。</p><p>“可是Dan，基因问题怎么算？我的出生地呢？还有我干着一份不给我留够时间的工作，吧啦吧啦吧啦……”</p><p>是的，这些事情有一定影响。</p><p>但你刚刚又做了一个微小的选择：封闭了你的思想，无视了在当前处境下你能做些什么。你刚刚放弃了你解决问题的能力……而这是唯一能让你自由的能力。</p><blockquote><p>选择的能力不能被剥夺，甚至也不能被让渡——它只能被遗忘。——格雷格·麦吉沃恩（Greg McKeown）</p></blockquote><p>不难看出，你并不是什么特例。成千上万像你一样的人已经扭转了他们的局面。我敢打赌，如果你面对一个处境糟糕的人，你能给他们指出实现某个目标的步骤，但你却无法为自己做同样的事，因为你的心智在阻碍你。</p><p>你一年后的生活质量，将取决于复利聚集成那种生活的微小选择。</p><p>你不必做出完美的选择。</p><p>如果你犯了错，实际上反而更好。</p><p>最大的风险就是根本不冒风险，否则你还能怎么失败呢？</p><p>没有失败，进步根本是不可能的。</p><p>没有进步，你对生活就没有目标。</p><p>失去生活目标，一切都会变得毫无意义。</p><p>成为一个更好的人，就是你有目标地生活的方式。</p><p>破产的人安于破产，直到发生灾难性的事情。</p><p>而且灾难性事件发生他们身上的可能性要大得多。</p><p>他们的汽车抛锚报废，因为太旧且缺乏保养。</p><p>有人闯入他们位于治安较差街区的房子。</p><p>他们的父母病了，而他们因为收入低而无能为力。</p><p>当然，到了这个时候，他们会有一些赚钱的动力，但当灾难性事件发生时，他们觉得为时已晚。他们没有做好准备。</p><p>于是他们陷入了“我本该早点开始的”无尽循环中。</p><p>最终，情况会趋于平稳。他们生活中的压力降低。他们重新开始享受毫无思想的安逸。等待着另一场灾难将他们击垮。</p><p><em>成功人士则利用这些事件来改变自己是谁。</em></p><p>他们是谁决定了他们的标准和价值观。</p><p>他们的标准和价值观决定了他们做出的每一个微小的选择。</p><p>如果你能接受银行账户里只有5美元，你就不会认为这是个问题。</p><p>如果你能接受银行账户里有10万美元，你就会认为任何低于这个数目的情况都是需要解决的问题。</p><p>问题构建了你的认知——我<a href="https://theartoffocusbook.com/" target="_blank" rel="noreferrer">在我的书里</a>谈论过这个。</p><p>你开始注意到更多赚钱的机会。</p><p>你的谷歌搜索变成了诸如“如何每月多赚1000美元”这样的内容。</p><p>你开始和朋友们进行关于金钱的对话。</p><p>所有这些微小的选择开始产生复利，转化为结果。</p><p>你根据对与你所面临的问题相关的特定信息的有意搜索，重塑了你的思维模式。</p><p>你消费的信息深刻影响着你的身份认同，从而影响着你的标准。</p><p>如果你身边围绕的人——无论是在现实中还是在数字世界里——让你觉得超重100磅、身无分文、干着讨厌的工作、和鄙视的伴侣在一起、每晚喝得烂醉等等都是“可以接受的”……你认为你的生活最终会变成什么样？</p><p>如果你的标准要求你吃全食超市（Whole Foods）的食物，你就会厌恶地看待麦当劳的快餐。</p><p>如果你的标准要求你像CEO一样工作，你就会把低级的苦力活看作是一个必须通过获取技能、教育、设定优先级和外包来解决的问题。</p><p>显然，你无法立刻解决你生活中的所有问题。</p><p>你现在也无法逃离你的处境。</p><p>你需要一个计划。一个目标。一条出路。</p><p>而且，只要坚持这个计划，我保证，这段旅程将比那件事的结果更令人愉悦。</p><p>正如尼采所说：</p><p>“幸福就是权力感增加的感觉——也就是阻力正在被克服。”</p><h3 id="你想成为什么样的人的标准" tabindex="-1">你想成为什么样的人的标准 <a class="header-anchor" href="#你想成为什么样的人的标准" aria-label="Permalink to &quot;你想成为什么样的人的标准&quot;">​</a></h3><p>大多数人对生活采取只求满足最低标准的态度。</p><p>赚快钱，快餐式性爱，短暂的快感，没有承诺，没有深度，也没有失败。</p><p>你越是想让生活变得轻松，生活就会变得越艰难。</p><p>摆脱盲目生活的出路，是采纳你想成为的那个人的标准。</p><p>你想赚多少钱？</p><p>哪种工作能给你带来充实感？</p><p>无论是朋友还是伴侣，你理想中的关系是怎样的？</p><p>你想拥有怎样的外表和感觉？</p><p>你必须超越生存的最低底线。</p><p>致力于为你的行动找到理由。</p><p>如果你不知道自己为什么要这样做，那你为什么还要做？如果你知道原因，那你为什么要忽视它？</p><p>你在星巴克工作，递出40杯加了三泵糖浆的摩卡卡布奇诺，是在推动人类进步吗？还是在让人类生病和超重？</p><p>还有你那份“无辜的”前台工作，为一个在地球另一端轰炸无辜平民的军工复合体服务，这又怎么说？</p><p>你是否意识到你正在无意识地助长些什么？</p><p>你为什么还没有开始追求一份更有目标的职业，或者去创业？</p><p>你知道为什么你要把食物胡乱塞进喉咙吗？你了解每种营养素如何与你的生理机能相互作用并创造健康状态吗？</p><p>你为什么还没有开始在健康和锻炼方面教育自己？</p><p>你住在这个身体里。了解它应该被视为你的全职工作。</p><p>你知道为什么你要和那个容易追到手的伴侣敷衍了事地过日子吗？你能想象自己和他们再过40年吗？</p><p>你为什么没有把你的社交技巧提升到能够吸引更好伴侣的地步？</p><p>这很陈词滥调，但人生只有一次。</p><p>唯一能阻止你过毫无意义生活的人，就是你自己。</p><h3 id="为自己设定的7个标准" tabindex="-1">为自己设定的7个标准 <a class="header-anchor" href="#为自己设定的7个标准" aria-label="Permalink to &quot;为自己设定的7个标准&quot;">​</a></h3><p>让我们快速列举7个能带来充实未来的标准：</p><ol><li><strong>1小时的深度工作</strong> —— 如果你能花8小时去构建别人的梦想，你就能花1小时来构建你自己的。</li><li><strong>银行里有10万美元</strong> —— 少于这个数都应被视为一个亟待解决的问题。这个标准为你的选择提供了财务方向和清晰度。</li><li><strong>每天走10000步</strong> —— 为了身心健康。燃烧卡路里，晒晒太阳，让大脑敞开接纳新想法。所有重大的发现，比如原子弹的诞生，都是在散步时被构想出来的。</li><li><strong>每磅体重摄入1克蛋白质</strong> —— 这能让你有饱腹感，增长肌肉，并让你更容易摄入充足的常量和微量营养素。即使你不打算增肌，也应优先考虑高蛋白食物的热效应和微量营养素密度。当你做到这一点时，你的大部分减脂或日常饮食问题基本就水到渠成了。</li><li><strong>每周训练3次以上</strong> —— 跑步、骑车、奥林匹克举重、健美、混合健身（CrossFit），我不在乎你练什么。做一些能促进血液循环、延长寿命的运动，并把它当作一种冥想习惯，让你的大脑从工作中解脱出来休息一下。</li><li><strong>每月1次自我投资</strong> —— 付费的人才会用心。别把钱浪费在短暂的快乐上，而是投资于教育、业务增长以及那些能让你成为理想自我的体验上。</li><li><strong>30分钟的自我教育</strong> —— 如果你不能每天学点新东西，你就是在慢慢走向死亡。自我教育会重新对你的大脑进行编程。没有它，你无法发现能改变生活的新机遇。</li></ol><p>这些标准是你需要逐渐成长去适应的。它们不可能一夜之间达成。</p><p>你通过改变所消费的信息来重塑你的大脑，使之与这些标准保持一致，然后，当你达不到这些标准时，你就会感受到压力反应。那就是你的新身份在努力求生。</p><p>你可以利用这种压力去采取行动、解决问题并进行创造。</p><h2 id="如何创造你的理想生活方式" tabindex="-1">如何创造你的理想生活方式 <a class="header-anchor" href="#如何创造你的理想生活方式" aria-label="Permalink to &quot;如何创造你的理想生活方式&quot;">​</a></h2><p>让我们来拆解一下是什么造就了更好的选择：</p><p>学习是人类最基本的驱动力。</p><p>一出生，你就是一块信息海绵。</p><p>你的父母、朋友、社会、老师和老板都会把他们的世界观投射到你身上。</p><p>他们的世界观又是从哪来的？也是从这些人那里来的，除非他们曾对其提出过质疑。</p><p>这就是你所知道的全部。</p><p>如果我们能用数字来量化，你所知道的还不到世界上可用信息的1%。甚至可能接近于不到0.001%。</p><p>这些信息在现实中建立了各种参考点。</p><p>这就是你如何将自己与他人区分开来的方式。</p><p>它塑造了你的身份。</p><p>你的身份限制了你能注意到的信息，因为你学到的就只有那么多。如果你没有学过能够将某事物与你现有认知联系起来的信息，你就不会注意到它。如果你没有学过初级信息，你就不会理解中级信息。你无法直接从第1级跳到第3级。正因如此，你正在错失99%的生活。</p><p>如果我接触到了那些让我变成哥特风（goth）的信息和环境，我就会在音乐、人际交往、服装、工作机会、对未来的展望以及情绪状态上表现出特定的好恶。</p><p>作为一个哥特风的人，我不会注意到、甚至根本不在乎什么有利可图的商业试错机会（假设我是那种讨厌世界的典型孤独哥特族）。</p><p>如果我随着时间的推移，把自己沉浸在海量信息中来重新编程我的身份，我就会发现与那个新身份相关的机会。</p><p>这就引出了互联网的力量。</p><p>你可以去打理一座数字花园，也可能被推入一片数字沼泽。</p><p>我们从未接触过如此庞大的信息，我很难相信它不是在迅速地——且越来越糟地——重塑人们的身份。</p><p>当你登录社交媒体时，默认的动作就是去关注娱乐账号和梗图主页。</p><p>它们几乎全都会给你的大脑塞进一堆不受欢迎的租客，这些家伙在里面像开兄弟会派对一样狂欢。等父母回到家时，会被眼前的狼藉彻底崩溃。</p><p>而你的觉察力，就像是在那些无脑的想法把你的大脑变成沼泽后，回到家中的父母。</p><p>现在就意识到这一点吧。</p><p>取关任何无益于为你生活中更好标准提供条件的人。即使看起来不像，不管你如何为之辩解，你关注的人都在潜移默化地影响你的行为。起初很慢，然后突然之间，你就会变成一个你自己都可能讨厌的人。</p><p>花点时间去关注有价值的账号。有价值的账号会挑战你的世界观，让你跳出固有思维模式，并教会你实现更高质量生活所必需的技能。</p><p>这不是一个一蹴而就的过程。</p><p>起初你可能不会觉得这些信息有用。</p><p>建立能够通向理解的特定观念桥梁，是需要时间的。</p><p>你很可能会觉得它很无聊……直到它变成世界上最有趣的事情之一。</p><p>去关注一个账号。</p><p>让算法发挥它的作用。</p><p>关注那些回复第一个账号帖子的账号。</p><p>随着时间的推移，你就能创造出一个有利于你成长的环境。</p><p>你和比你更成功的人之间的唯一区别，就在于他们消费信息背后始终如一的意图。</p><p>“但是采取行动呢？？？”</p><p>你每天都在采取行动。</p><p>为什么？</p><p>因为你的大脑被编入了那些促成这些行动的信息。</p><p>你的身份是由你被喂养的信息所塑造的，单凭这一点就决定了你眼中能被视为行动机会的东西。</p><p>让你身边充满对的人，你就能实现你想要的任何事情。</p><h3 id="价值创作者之路" tabindex="-1">价值创作者之路 <a class="header-anchor" href="#价值创作者之路" aria-label="Permalink to &quot;价值创作者之路&quot;">​</a></h3><p>为什么人们总是不断地做自己讨厌的事情？</p><p>我一直对此感到疑惑。</p><p>倒不是说我是个从未掉进过陷阱的特殊小花朵，但我确实感觉自己已经逃离了出来，并且能从山上更高的地方俯瞰局势，直到我不可避免地再次跌落。</p><p>祈盼着周末。</p><p>恐惧着周一早晨。</p><p>隐藏真实的自我，去和那些你根本不喜欢共事的人套近乎。</p><p>把互联网当作逃避的避风港。</p><p>滑动、点击，让你的大脑再多关闭一会儿，因为当它清醒运转时，你不喜欢它在做的事情。</p><p>这就是消费者的生活。</p><p>是被互联网利用的人，而不是利用互联网的人。</p><p>这个新世界是无法逃避的。</p><p>你可以反抗它，或者顺应它。</p><p>虽然互联网是问题的所在，但它也是解决之道。</p><p>你并非必须使用互联网来做到这一点，但根本没有理由不用它。</p><p>你的生活之所以糟糕，最后一个原因就是你没有对人类做出贡献。</p><p>你缺乏<em>目标。你没有参与到某个比你自己更宏大且由</em> <em><strong>你亲自选择的</strong></em> <em>事业中去。</em></p><p><em>你没有对人类做出贡献，是因为你没有拥有那种有价值到让你忍不住想要分享的东西。</em></p><p>你没有有价值的东西可以提供，是因为你忽视了自己生活中那些亟待寻找解决方案的问题。</p><p>你忽视生活中的问题，是因为你对于如何实现能够解决这些问题的目标缺乏清晰的认识。</p><p>你对如何实现目标缺乏清晰的认识，是因为你什么都没有在构建。没有任何东西来框架和引导你的学习。</p><p>价值创作者是那些在输入和输出背后带有明确意图的人。</p><p>他们把自己的生活当成一个科学项目来对待。</p><p>他们识别出自己的问题。</p><p>他们利用互联网上无限的可用资源来进行自我教育。</p><p>他们在自己身上测试解决方案，并通过写作来分发他们的经验。</p><p>他们将最有用、最精简的解决方案打包成产品或服务的形式。</p><p>这就是他们如何通过有目的地生活来谋生的方式</p><p>成为一名创作者是过度消费的解药。</p><p>写作是分发价值的载体。</p><p>我在所有平台上写作。我懒得用豪车或生活方式的照片去与别人竞争。我获得了一种深深的满足感，因为我把互联网不仅当作收集好想法的地方，而且在这里整理它们、与他人分享，其最终的好处是能以我喜欢做的事情为生。这是在我的掌控之中的。</p><p>这与出名无关。</p><p>这与建立庞大的粉丝群无关。</p><p>这是关于在一个可以触达任何人的地方，分发你所能提供的价值，随之而来的是那些将改变你生活和职业生涯的机遇。</p><p>你不需要一门手把手的课程来加入这场在线派对。</p><p>写你想写的东西。</p><p>和你想交谈的人交谈。</p><p>别像个幽灵一样潜水，让你的名字出现在人们面前。</p><p>让别人看到你的文字，这样随着时间的推移，它就能传播得越来越广。</p><p>如果你真的需要额外的推力，那就去观察你关注的那些人，观察足够长的时间。</p><p>观察他们写些什么。</p><p>观察他们是怎么写的。</p><p>观察他们和谁互动。</p><p>观察他们靠卖什么来谋生。</p><p>把这些点滴拼凑起来，开始模仿他们。</p><p>如果你没有答案，就去查。</p><p>你不可能在一瞬间得到所有的答案。</p><p>接受这一点。</p><p>如果你知道自己注定不凡，那就开始付诸行动。</p><p>你并非必须写作，但我已经尝试过所有方法了。</p><p>由于写作是在整个人类历史上幸存下来的最基本的沟通方式，它是发现你真正想做之事的绝佳起点。</p><h3 id="如何开始期待周一的早晨" tabindex="-1">如何开始期待周一的早晨 <a class="header-anchor" href="#如何开始期待周一的早晨" aria-label="Permalink to &quot;如何开始期待周一的早晨&quot;">​</a></h3><p>你不期待起床，是因为你没有值得期待的东西。</p><p>这很显而易见，但依然是一个普遍存在的问题。</p><p>人们不把它看作是一个问题，因此他们成了自身处境的受害者，把无法<em>开辟</em>新道路的责任怪罪给除了自己以外的所有人。</p><p>你可以尝试下面这个流程，去找到那件让你根本睡不着懒觉的事情：</p><p><strong>1) 规划一个全局的未来</strong></p><p><img src="'+o+'" alt=""></p><p>你需要一个愿景，以及一个反向愿景（anti-vision）。</p><p>拿出一个笔记本，开始写。</p><p>把你在未来不想要的一切都倾倒出来。从过往经验和现状中提取，当你意识到有更多东西需要添加到页面上时，继续写下去。这是一份生生不息的活文档。你不能只是写个10分钟，然后就把它抛到脑后。</p><p>你的反向愿景应该极具冲击力。强烈到让你对自己的现状感到恶心。你应该想和它撇清一切关系。你唯一的选择就是朝着相反的方向发射。</p><p>从那里开始，写下它的对立面。</p><p>开始清晰地描绘出你在未来想要什么。在下个月体验生活的过程中，不断补充进去。</p><p>接下来，再写下几件事：</p><ul><li>确切地写下在接下来的一年、一个月和一周里，你需要做什么来开始取得进展。</li><li>确切地写下为了实现目标，你需要学习哪些技能。</li><li>写下目前是什么在阻碍你，以及你替换掉那些习惯（或人）的计划。</li><li>写下为了实现未来的愿景，你需要成为什么样的人。</li></ul><p>那至少应该能给你一个起点。</p><p><strong>2) 创办一家企业</strong></p><p>“但是Dan，我不想创业啊！！！！”</p><p>你还是没搞懂，对吧？</p><p>除非你的愿景并不真实——意思是你并没有去顺从父母或社会对你未来的期望——否则，能够完全掌控你生活各个领域的唯一途径就是创办一家企业。</p><p>不想被取代？那就成为那个取代别人的人。</p><p>没有精力且无法集中注意力？创办一家企业吧，这样你就能控制自己的工作时间，并专注于健康。</p><p>赚得不够多？那就创办一家有极高收入上限（或者说无限学习上限）的企业，这几乎总是从一家需要0美元启动资金的在线企业开始的。</p><p>缺乏意义和成就感？那是因为你从事的工作中，挑战已经不复存在。你为你不在乎的人工作，卖你不在乎的产品，耗尽你的精力去创造一种你不在乎的生活。</p><p>你的心理、生理和精神状态一团糟，仅仅是因为你没有把主动权掌握在自己手中。</p><p>是的，很遗憾“创业”带有太多陈旧的内涵。</p><p>至少在我看来，企业只是让你允许自己去做想做的事。</p><p>如果你想创造理想的一天，那你就需要完全掌控它。</p><p>是的，这需要时间，但这段旅程将比你做的任何事情都更有成就感。</p><p><strong>3) 每天自我教育</strong></p><p>这显而易见，但除此之外，你还能如何去学习<em>怎样</em>做你想做的事呢？</p><p>讲点逻辑吧。</p><p>你不能有这么多梦想和抱负，却表现得好像你什么都不需要学一样。</p><p>投资参加研讨会。</p><p>投资购买课程。</p><p>投资去体验。</p><p>投资业务增长。</p><p>把你拥有的一切投资到创造你想要的生活上。否则，那就不是投资，而是浪费。</p><p>每天专门留出30到60分钟的时间用于自我教育。</p><p>你可以把它和生活中的其他标准结合起来，比如每天走一万步。</p><p>去散散步，放一集播客、讲座或有声书，让自己接触那些你不知道的东西，并捕捉有力的想法，这样你在专注工作的时间段里就有燃料去构建。用 <a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a> 来捕获这些想法。</p><p><strong>4) 系统化你的每周和每天</strong></p><p>如果你没有在进步，你就是在退步。</p><p>我甚至都不确定这语法对不对，但你明白我的意思。</p><p>熵并不友善。</p><p>你永远不会停滞不前，你要么前进，要么在不知不觉中后退。</p><p>所以，如果你没有在进步，你必须能够意识到这是一个问题，并开始深入挖掘它。</p><p>从每周审计开始。</p><p>写下你每天做的每一件事，并开始给它们打上不必要或寄生性的标签。</p><p>然后，拿出一张白纸，画一个每周日历，写下你那周要做的每一件事。这些事应该与实现你的目标所取得的进展相一致。</p><p>然后，开始行动。</p><p>如果有些事情做起来不顺畅，就在纸上把它划掉，换成别的事情。</p><p>如果你没有取得进展，就尝试做点别的事情。</p><p><strong>5) 自我实验</strong></p><blockquote><p>永远解决你问题的唯一方法是通过自我实验。——《专注的艺术》（The Art Of Focus）</p></blockquote><p>有一个巨大的问题。</p><p>如果你只专注于通过实验来解决你生活中的问题，你就会变得成功。</p><p>但没有人这么做。</p><p>他们被推销去上学、找工作、买房、买车和退休。所以人们追求这些，把它当成解决他们根深蒂固问题的创可贴。</p><p>然后，他们被塞给食物、药物和建议，在上面又贴了一层创可贴。因此，人们慢慢变得越来越神经质和愚蠢，因为他们未能真正解决生活中的问题。而解决问题，正是让你变得有价值、不可替代、聪明、清醒，以及获得你所能拥有的任何其他好品质的关键。</p><p>当你走上这条新路，远离你的反向愿景并走向你的愿景时，你成功的决定因素是能动性：</p><p>无需他人允许就能发现和解决问题的能力。</p><p>当你遇到问题时：</p><ul><li>察觉到它</li><li>开始自我教育来解决它</li><li>尝试不同的过程和教导</li><li>不要执着于任何特定的一个（就像纯肉饮食法，它可能会在一年左右的时间里对你有用，让你变得更健康，直到它走向反面并对你的健康造成严重破坏）。</li></ul><p>解决方案会根据你的情况而改变和进化。</p><p>你可能永远也找不到永久的解决方案。</p><p>也就是说，如果你一旦不再关注提升，你就会开始退步。</p><p>这并不意味着你不再享受乐趣。创造与毁灭是在循环中发生的。自我提升如果做得太过火，也会跌入毁灭的境地，但到了那个地步，这就已经不是自我提升了。所以，那时候的自我提升就会变成放飞自我，去做那些被大多数人贴上“毁灭性”标签的事情，而从这个角度来看，它其实是创造性的。</p><p>这期就到这里。</p><p>感谢你的阅读。</p><p>—— Dan</p><hr><p><a href="/en/letters/the-uncertainty-crisis-why-everyone-feels-so-lost">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',389))])}const x=l(d,[["render",f]]);export{w as __pageData,x as default};
